pub struct CountWordsUseCase {
    uow_factory: Box<dyn CountWordsUnitOfWorkFactoryTrait>,
    dto: CountWordsDto,
}

impl CountWordsUseCase {
    pub fn new(
        uow_factory: Box<dyn CountWordsUnitOfWorkFactoryTrait>,
        dto: &CountWordsDto,
    ) -> Self {
        CountWordsUseCase {
            uow_factory,
            dto: dto.clone(),
        }
    }
}

impl LongOperation for CountWordsUseCase {
    type Output = WordCountResultDto;

    fn execute(
        &self,
        progress_callback: Box<dyn Fn(OperationProgress) + Send>,
        cancel_flag: Arc<AtomicBool>,
    ) -> Result<Self::Output> {
        progress_callback(OperationProgress::new(0.0, Some("Starting…".to_string())));

        let uow = self.uow_factory.create();
        uow.begin_transaction()?;
        // Always close the frozen-read transaction, even on error.
        let outcome = run_count(&*uow, &self.dto, &progress_callback, &cancel_flag);
        uow.end_transaction()?;

        let (work_id, result) = outcome?;
        uow.publish_count_words_event(vec![work_id], None);
        progress_callback(OperationProgress::new(100.0, Some("completed".to_string())));
        Ok(result)
    }
}

fn run_count(
    uow: &dyn CountWordsUnitOfWorkTrait,
    dto: &CountWordsDto,
    progress: &(dyn Fn(OperationProgress) + Send),
    cancel: &AtomicBool,
) -> Result<(EntityId, WordCountResultDto)> {
    // Count exactly the Work the caller named — `gather` requires it explicitly.
    let g = gather(uow, dto.work_id as EntityId, progress, cancel)?;
    let work_id = g.work.id;

    // The persisted history uses `Auto` resolved from the project's language — CJK-correct
    // for Chinese/Japanese projects, UnicodeWords otherwise. (The user's explicit
    // method override only affects the live status-bar display, not this canonical record.)
    let method = counting::resolve_method(
        CountingMethodSetting::Auto,
        CountMethod::UnicodeWords,
        language::primary(&g.work.dict_language),
    );

    // The SceneText prose of each item (gather already fetched contents per item).
    let mut prose_by_item: HashMap<EntityId, Vec<String>> = HashMap::new();
    for bwi in &g.binders {
        for iwc in &bwi.items {
            let scene: Vec<String> = iwc
                .contents
                .iter()
                .filter(|c| c.activated && c.role == ContentRole::SceneText)
                .map(|c| c.data.clone())
                .collect();
            if !scene.is_empty() {
                prose_by_item.insert(iwc.item.id, scene);
            }
        }
    }

    // Footnote prose, bucketed by the item whose Content each note annotates, so it
    // can be attributed to the same Book the manuscript walk attributes prose to.
    //
    // `fwc.footnote.content` is trusted at face value here, same as in
    // `search_management::run_search_uc::footnote_fields` — safe only because
    // `binder_item_management`'s `split_scene`/`merge_two_scenes` now keep it
    // reparented whenever a note's citation is relocated to a different `Content` row
    // (see `binder_item_management::footnote_reanchor`). Before that, a split or merge
    // could leave this pointing at a row the citation no longer lived in (misattributed
    // to the wrong item/Book) or at a row whose owning item was trashed by the merge
    // (silently dropped from every total). `skribisto_model::footnote_numbering` — the
    // editor badge and the Footnotes dock — never reads this field at all; it re-derives
    // a note's place by scanning live prose, so it never showed the drift. Only a reader
    // that trusts the stored anchor, like this one, could.
    let mut content_owner: HashMap<EntityId, EntityId> = HashMap::new();
    for bwi in &g.binders {
        for iwc in &bwi.items {
            for c in &iwc.contents {
                content_owner.insert(c.id, iwc.item.id);
            }
        }
    }
    let mut notes_by_item: HashMap<EntityId, Vec<String>> = HashMap::new();
    for fwc in &g.footnotes {
        // An orphaned note belongs to no item and so to no Book. It is still the
        // writer's prose, but there is nothing to attribute it to — and inventing an
        // attribution would put words in a Book that does not contain them.
        let Some(content_id) = fwc.footnote.content else {
            continue;
        };
        let Some(item_id) = content_owner.get(&content_id).copied() else {
            continue;
        };
        if !fwc.footnote.body.is_empty() {
            notes_by_item
                .entry(item_id)
                .or_default()
                .push(fwc.footnote.body.clone());
        }
    }

    let items = skribisto_compiler::item_metas(&g);
    Ok((
        work_id,
        fold_counts(&items, &prose_by_item, &notes_by_item, method),
    ))
}

/// One linear pass over the ordered compile stream: sum the SceneText prose of every
/// `activated && is_exportable` prose-bearing item, bucketed by the enclosing Book. Pure —
/// the store/gather boilerplate is separate so this (the real logic) is unit-testable.
fn fold_counts(
    items: &[ItemMeta],
    prose_by_item: &HashMap<EntityId, Vec<String>>,
    notes_by_item: &HashMap<EntityId, Vec<String>>,
    method: CountMethod,
) -> WordCountResultDto {
    let mut total_words: i64 = 0;
    let mut total_chars: i64 = 0;
    let mut current_book: Option<EntityId> = None;
    let mut current_binder: Option<u64> = None;
    let mut per_book: Vec<(EntityId, i64)> = Vec::new();
    let mut total_note_words: i64 = 0;
    let mut per_book_notes: Vec<(EntityId, i64)> = Vec::new();

    for m in items {
        // A book never runs past its own binder's edge. The stream is binder-major and
        // concatenated with nothing between one binder and the next, and only manuscript
        // rows ever carry `opens_book`/`closes_book` — so a book left open at the end of
        // the manuscript (no `BookEnd`, which only the shipped templates add) would
        // otherwise swallow every note and every old draft in the research binders and
        // report them as its own words. `skribisto_model::compile`'s own walks close the
        // book at this edge; this one has to agree with them, or the goal meter, the
        // analysis and the export describe three different books.
        if current_binder != Some(m.binder_id) {
            current_binder = Some(m.binder_id);
            current_book = None;
        }
        if m.sub_role.opens_book() {
            current_book = Some(m.id);
        } else if m.sub_role.closes_book() {
            current_book = None;
        }
        // "Exportable" = activated && is_exportable — the same admission
        // `footnote_numbering::counts` uses for numbering and for the export
        // preflight. A note is counted whenever its own row is in the book: a
        // note on a chapter the writer excluded from export is not in the book
        // either, but a note anchored to (say) a Book folder's synopsis is still
        // in the book even though a folder carries no `SceneText` of its own.
        if !(m.activated && m.is_exportable) {
            continue;
        }
        if let Some(notes) = notes_by_item.get(&m.id) {
            for body in notes {
                let c = counting::cached_count(body, method);
                total_note_words += c.words as i64;
                if let Some(book) = current_book {
                    match per_book_notes.iter_mut().find(|(id, _)| *id == book) {
                        Some(entry) => entry.1 += c.words as i64,
                        None => per_book_notes.push((book, c.words as i64)),
                    }
                }
            }
        }

        // The manuscript total is narrower than the note total: only a
        // prose-bearing row carries a `SceneText` body — exactly the compile
        // selection the exporter would emit.
        if !counts_prose(&m.role, &m.sub_role) {
            continue;
        }
        let Some(datas) = prose_by_item.get(&m.id) else {
            continue;
        };
        for data in datas {
            let c = counting::cached_count(data, method);
            total_words += c.words as i64;
            total_chars += c.chars_with_spaces as i64;
            if let Some(book) = current_book {
                match per_book.iter_mut().find(|(id, _)| *id == book) {
                    Some(entry) => entry.1 += c.words as i64,
                    None => per_book.push((book, c.words as i64)),
                }
            }
        }
    }

    // The book roster is the union of "has counted prose" and "has a counted note" —
    // not just the first. A Book folder carries no `SceneText` of its own, so a note
    // on its synopsis can leave it in `per_book_notes` with nothing in `per_book` at
    // all; dropping such a book here would silently lose its notes from the per-book
    // breakdown even though the global total (above) still counts them. Prose books
    // keep their existing order (several tests key off it); a notes-only book is
    // appended in the order its notes were found.
    let book_item_ids: Vec<u64> = per_book
        .iter()
        .map(|(id, _)| *id)
        .chain(
            per_book_notes
                .iter()
                .map(|(id, _)| *id)
                .filter(|id| !per_book.iter().any(|(b, _)| b == id)),
        )
        .collect();
    let book_word_counts: Vec<i64> = book_item_ids
        .iter()
        .map(|id| {
            per_book
                .iter()
                .find(|(b, _)| b == id)
                .map(|(_, n)| *n)
                .unwrap_or(0)
        })
        .collect();
    // Aligned with `book_item_ids` position for position, so a caller can read the two
    // side by side.
    let book_footnote_word_counts: Vec<i64> = book_item_ids
        .iter()
        .map(|id| {
            per_book_notes
                .iter()
                .find(|(b, _)| b == id)
                .map(|(_, n)| *n)
                .unwrap_or(0)
        })
        .collect();
    WordCountResultDto {
        total_word_count: total_words,
        total_char_count: total_chars,
        book_item_ids,
        book_word_counts,
        total_footnote_word_count: total_note_words,
        book_footnote_word_counts,
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use common::entities::{BinderItemRole, BinderItemSubRole};
    use skribisto_model::compile::ItemMeta;

    fn meta(id: u64, role: BinderItemRole, sub_role: BinderItemSubRole) -> ItemMeta {
        ItemMeta {
            id,
            binder_id: 1,
            role,
            sub_role,
            indent: 0,
            activated: true,
            is_exportable: true,
            exclude_from_numbering: false,
        }
    }

    #[test]
    fn counts_only_exportable_prose_bucketed_by_book() {
        use BinderItemRole::{Folder, Item};
        use BinderItemSubRole as SR;

        // Book folder(10) > chapter head(11, prose) + scene(12) + deactivated scene(13) +
        // non-exportable scene(14) + a note(15, not prose-bearing). BookEnd(16).
        let stream = vec![
            meta(10, Folder, SR::Book),
            meta(11, Folder, SR::ChapterScene),
            meta(12, Item, SR::Scene),
            {
                let mut m = meta(13, Item, SR::Scene);
                m.activated = false;
                m
            },
            {
                let mut m = meta(14, Item, SR::Scene);
                m.is_exportable = false;
                m
            },
            meta(15, Item, SR::Note),
            meta(16, Item, SR::BookEnd),
        ];
        let mut prose: HashMap<EntityId, Vec<String>> = HashMap::new();
        prose.insert(11, vec!["chapter one two".into()]); // 3 words (prose-bearing head)
        prose.insert(12, vec!["a b c d".into()]); // 4
        prose.insert(13, vec!["skip me now".into()]); // excluded (deactivated)
        prose.insert(14, vec!["skip me too".into()]); // excluded (non-exportable)
        prose.insert(15, vec!["a note here".into()]); // excluded (Note not prose-bearing)

        let out = fold_counts(
            &stream,
            &prose,
            &HashMap::new(),
            CountMethod::WhitespaceSplit,
        );
        assert_eq!(
            out.total_word_count, 7,
            "only the head (3) + the live scene (4)"
        );
        assert_eq!(out.book_item_ids, vec![10]);
        assert_eq!(out.book_word_counts, vec![7]);
    }

    #[test]
    fn prose_outside_any_book_counts_toward_the_total_but_no_bucket() {
        use BinderItemRole::Item;
        use BinderItemSubRole as SR;
        // A loose scene with no enclosing Book (no opens_book before it).
        let stream = vec![meta(20, Item, SR::Scene)];
        let mut prose: HashMap<EntityId, Vec<String>> = HashMap::new();
        prose.insert(20, vec!["one two three".into()]);
        let out = fold_counts(
            &stream,
            &prose,
            &HashMap::new(),
            CountMethod::WhitespaceSplit,
        );
        assert_eq!(out.total_word_count, 3);
        assert!(out.book_item_ids.is_empty(), "no Book → no per-book bucket");
    }

    /// **A book stops at its own binder's edge.**
    ///
    /// The stream is binder-major and concatenated with nothing between one binder and the
    /// next, and only manuscript rows carry `opens_book`/`closes_book`. A hand-made Book
    /// with no closing `BookEnd` (only the shipped templates add one) therefore stays open
    /// past the end of the manuscript, and every old draft the writer keeps in a research
    /// binder lands in its bucket: the per-book goal meter fills with words the export and
    /// the analysis, which both close the book here, say are not in the book at all.
    #[test]
    fn a_book_left_open_does_not_swallow_the_next_binder() {
        use BinderItemRole::{Folder, Item};
        use BinderItemSubRole as SR;

        // Manuscript binder: a Book with one scene and NO BookEnd.
        // Research binder: an old draft, activated and exportable like any other row.
        let mut research = meta(30, Item, SR::Scene);
        research.binder_id = 2;
        let stream = vec![
            meta(10, Folder, SR::Book),
            meta(11, Folder, SR::ChapterScene),
            meta(12, Item, SR::Scene),
            research,
        ];
        let mut prose: HashMap<EntityId, Vec<String>> = HashMap::new();
        prose.insert(12, vec!["a b c d".into()]); // 4
        prose.insert(30, vec!["one two three four five six".into()]); // 6

        let out = fold_counts(
            &stream,
            &prose,
            &HashMap::new(),
            CountMethod::WhitespaceSplit,
        );
        assert_eq!(
            out.total_word_count, 10,
            "every activated exportable scene still counts toward the work's total"
        );
        assert_eq!(out.book_item_ids, vec![10]);
        assert_eq!(
            out.book_word_counts,
            vec![4],
            "but the research binder's draft is not in the Book"
        );
    }

    /// **The fork this feature turns on.** A footnote IS authored words — unlike an
    /// epigraph's quoted matter — so the number must not be discarded. But folding it
    /// into the manuscript total would make a heavily annotated chapter report
    /// progress the story did not make, and a writer's daily goal and pace projection
    /// are both built on that total. Two numbers, one meaning each.
    #[test]
    fn footnote_words_are_counted_apart_from_the_manuscript() {
        let stream = vec![meta(1, BinderItemRole::Item, BinderItemSubRole::Scene)];
        let mut prose = HashMap::new();
        prose.insert(1u64, vec!["one two three".to_string()]);
        let mut notes = HashMap::new();
        notes.insert(1u64, vec!["a four word note".to_string()]);

        let out = fold_counts(&stream, &prose, &notes, CountMethod::WhitespaceSplit);

        assert_eq!(
            out.total_word_count, 3,
            "the manuscript total must not move when a note is added"
        );
        assert_eq!(
            out.total_footnote_word_count, 4,
            "the notes have their own total"
        );
    }

    /// Adding a note changes the footnote total and nothing else.
    #[test]
    fn adding_a_note_leaves_every_manuscript_number_alone() {
        let stream = vec![meta(1, BinderItemRole::Item, BinderItemSubRole::Scene)];
        let mut prose = HashMap::new();
        prose.insert(1u64, vec!["one two three".to_string()]);

        let without = fold_counts(
            &stream,
            &prose,
            &HashMap::new(),
            CountMethod::WhitespaceSplit,
        );
        let mut notes = HashMap::new();
        notes.insert(1u64, vec!["several extra words here".to_string()]);
        let with = fold_counts(&stream, &prose, &notes, CountMethod::WhitespaceSplit);

        assert_eq!(without.total_word_count, with.total_word_count);
        assert_eq!(without.total_char_count, with.total_char_count);
        assert_eq!(without.book_word_counts, with.book_word_counts);
        assert_eq!(without.total_footnote_word_count, 0);
        assert_eq!(with.total_footnote_word_count, 4);
    }

    /// **Regression.** A note anchored to a row that carries no `SceneText` of its
    /// own — a Book folder's synopsis, say — is still `activated && is_exportable`,
    /// so `footnote_numbering::counts` places and numbers it, and the export
    /// preflight counts it as referenced. The word count must agree: it used to sit
    /// behind the same `counts_prose` gate as the manuscript prose, so a note here
    /// was silently dropped from every total even though it is very much in the
    /// book.
    #[test]
    fn a_note_on_a_row_with_no_scene_text_still_counts() {
        use BinderItemRole::Folder;
        use BinderItemSubRole as SR;
        // A Book folder: `counts_prose(Folder, Book)` is false (only Folder/ChapterScene
        // and the Item encodings carry SceneText), but the folder is still activated
        // and exportable — its own synopsis can carry a reference.
        let stream = vec![meta(10, Folder, SR::Book)];
        let mut notes = HashMap::new();
        notes.insert(10u64, vec!["a book synopsis note".to_string()]);

        let out = fold_counts(
            &stream,
            &HashMap::new(),
            &notes,
            CountMethod::WhitespaceSplit,
        );

        assert_eq!(
            out.total_word_count, 0,
            "the folder itself carries no prose"
        );
        assert_eq!(
            out.total_footnote_word_count, 4,
            "the note must still be counted, even off a non-prose-bearing row"
        );
        // The book has to show up in the per-book breakdown too, or the writer's
        // "words in this book" figure disagrees with the manuscript-wide total.
        assert_eq!(
            out.book_item_ids,
            vec![10],
            "a notes-only book must not be dropped"
        );
        assert_eq!(out.book_word_counts, vec![0]);
        assert_eq!(out.book_footnote_word_counts, vec![4]);
    }
}
